    if (i === 6) {
      colourBy(H[1].R); setBadge("M-step", "responsibilities FIXED · components move", "M"); chartUpTo(3);
      H[1].comps.forEach(function (c, k) { setCompEllipse(ghost[k], G, c, 1.5); });
      tween(H[1].comps, H[1].next);
